"use client"

/**
 * 事故受付センター 受付画面
 *
 * 相手は事故に遭ったばかりで、話す順番はばらばらで、後戻りもする。
 * だからこの画面は上から順に埋めさせない。どの項目からでも触れて、
 * 聞けなかったところは「まだ聞いていない」として残せるようにしてある。
 *
 * 表示している氏名・車・場所・番号は、すべて架空の見本です。
 */

import * as React from "react"
import {
  Badge,
  Button,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  Cluster,
  CopyButton,
  DatePicker,
  DesktopPageHeader,
  Icon,
  Input,
  RevealSection,
  Select,
  Separator,
  Textarea,
  TimePicker,
  VStack,
} from "@gunjo/ui"
import {
  IconCarGarage,
  IconCircleCheck,
  IconCircleDashed,
  IconClock,
  IconTruckDelivery,
} from "@tabler/icons-react"

import {
  AskChoiceField,
  AskField,
  AskSelectField,
  AskTextField,
} from "./AskField"
import { ContractFinder } from "./ContractFinder"
import { HearingProgress, type ProgressItem } from "./HearingProgress"
import { TodayList } from "./TodayList"
import {
  ASK_ITEMS,
  NEXT_OWNERS,
  NEXT_RECEIPT_NO,
  NEXT_TIMINGS,
  OPERATOR_LABEL,
  ROAD_OPTIONS,
  TODAY_LABEL,
  WEATHER_OPTIONS,
  type Contract,
} from "./data"
import {
  NO_DISPATCH,
  UNASKED,
  type Answer,
  type Answers,
  type AskId,
  type DispatchState,
} from "./types"

const EMPTY_ANSWERS: Answers = {
  date: UNASKED,
  time: UNASKED,
  place: UNASKED,
  weather: UNASKED,
  road: UNASKED,
  otherParty: UNASKED,
  otherName: UNASKED,
  otherPhone: UNASKED,
  otherCar: UNASKED,
  injury: UNASKED,
  ambulance: UNASKED,
  police: UNASKED,
  drivable: UNASKED,
  carPlace: UNASKED,
}

/** 「10:42」。通話中に押した時刻を記録するので、描画中ではなく操作時にだけ呼ぶ。 */
function clock(): string {
  const now = new Date()
  return `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`
}

function formatDate(date: Date): string {
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`
}

export default function AccidentIntakePage() {
  const [resetToken, setResetToken] = React.useState(0)
  const [contract, setContract] = React.useState<Contract | null>(null)
  const [withoutContract, setWithoutContract] = React.useState(false)

  const [answers, setAnswers] = React.useState<Answers>(EMPTY_ANSWERS)
  const [accidentDate, setAccidentDate] = React.useState<Date | undefined>(undefined)
  const [memo, setMemo] = React.useState("")

  const [tow, setTow] = React.useState<DispatchState>(NO_DISPATCH)
  const [rental, setRental] = React.useState<DispatchState>(NO_DISPATCH)

  const [nextOwner, setNextOwner] = React.useState(NEXT_OWNERS[0])
  const [nextTiming, setNextTiming] = React.useState(NEXT_TIMINGS[1])
  const [receiptNo, setReceiptNo] = React.useState<string | null>(null)

  const setAnswer = (id: AskId, answer: Answer) =>
    setAnswers((current) => ({ ...current, [id]: answer }))

  const hasOtherParty = answers.otherParty.status === "answered" && answers.otherParty.value === "いる"

  const progressItems: ProgressItem[] = ASK_ITEMS.filter(
    (item) => !item.onlyWhenOtherParty || hasOtherParty
  ).map((item) => ({ ...item, status: answers[item.id].status }))

  const unaskedCount = progressItems.filter((item) => item.status === "unasked").length

  /** 手配を頼む。少しあとに手配先から返事が来る、という見本の動き。 */
  const requestDispatch = (
    setter: React.Dispatch<React.SetStateAction<DispatchState>>,
    reply: string
  ) => {
    const at = clock()
    setter((current) => ({ ...current, requestedAt: at, answeredAt: null, reply: null }))
    window.setTimeout(() => {
      setter((current) =>
        current.requestedAt === null ? current : { ...current, answeredAt: clock(), reply }
      )
    }, 2000)
  }

  const resetAll = () => {
    setContract(null)
    setWithoutContract(false)
    setAnswers(EMPTY_ANSWERS)
    setAccidentDate(undefined)
    setMemo("")
    setTow(NO_DISPATCH)
    setRental(NO_DISPATCH)
    setNextOwner(NEXT_OWNERS[0])
    setNextTiming(NEXT_TIMINGS[1])
    setReceiptNo(null)
    setResetToken((token) => token + 1)
    window.scrollTo({ top: 0 })
  }

  const rentalIncluded = contract?.coverages.find((item) => item.key === "rental")?.included ?? false
  const towIncluded = contract?.coverages.find((item) => item.key === "tow")?.included ?? false

  const spokenText = receiptNo
    ? `受付番号は ${receiptNo} です。${nextOwner}から、${nextTiming}にご連絡します。`
    : ""

  return (
    <div className="min-h-screen bg-background text-foreground">
      <div className="sticky top-0 z-20 border-b border-border bg-background px-4 py-3 lg:px-6">
        <DesktopPageHeader
          className="border-b-0 pb-0"
          eyebrow={`${TODAY_LABEL} ／ ${OPERATOR_LABEL}`}
          title="事故受付"
          subtitle="通話しながら、聞けたところから埋められます。順番どおりでなくて構いません。"
          actions={
            <Cluster gap={2}>
              <Badge
                variant="outline"
                icon={<Icon icon={IconCircleDashed} size="xs" decorative />}
              >
                まだ聞いていない {unaskedCount}件
              </Badge>
              {receiptNo ? (
                <Badge variant="success" icon={<Icon icon={IconCircleCheck} size="xs" decorative />}>
                  受付番号 {receiptNo}
                </Badge>
              ) : null}
            </Cluster>
          }
        />
      </div>

      <div className="mx-auto w-full max-w-[1600px] px-4 py-4 lg:px-6">
        <p className="mb-4 text-xs text-muted-foreground">
          この画面に出ている氏名・車・場所・番号・保険の内容は、すべて架空の見本です。
        </p>

        <div className="grid grid-cols-1 gap-4 lg:grid-cols-[minmax(0,1fr)_360px]">
          <main className="flex min-w-0 flex-col gap-4">
            <ContractFinder
              key={resetToken}
              selected={contract}
              onSelect={setContract}
              withoutContract={withoutContract}
              onWithoutContractChange={setWithoutContract}
            />

            {/* ---------------------------------------------------- 事故の状況 */}
            <Card id="sec-situation">
              <CardHeader>
                <CardTitle as="h2">事故の状況</CardTitle>
                <p className="text-sm text-muted-foreground">
                  場所は正確な住所でなくて構いません。目印だけで十分です。
                </p>
              </CardHeader>
              <CardContent>
                <VStack gap={3}>
                  <AskField
                    askId="date"
                    label="事故の日付"
                    answer={answers.date}
                    onAnswerChange={(answer) => {
                      if (answer.status !== "answered") setAccidentDate(undefined)
                      setAnswer("date", answer)
                    }}
                  >
                    {({ controlId }) => (
                      <DatePicker
                        id={controlId}
                        value={accidentDate}
                        placeholder="日付を選ぶ"
                        onValueChange={(date) => {
                          setAccidentDate(date)
                          setAnswer(
                            "date",
                            date ? { status: "answered", value: formatDate(date) } : UNASKED
                          )
                        }}
                      />
                    )}
                  </AskField>

                  <AskField
                    askId="time"
                    label="事故のおおよその時刻"
                    hint="だいたいで構いません。"
                    answer={answers.time}
                    onAnswerChange={(answer) => setAnswer("time", answer)}
                    labelAs="group"
                  >
                    {() => (
                      <TimePicker
                        label="事故のおおよその時刻"
                        minuteStep={5}
                        value={answers.time.status === "answered" ? answers.time.value : ""}
                        onValueChange={(value) =>
                          setAnswer(
                            "time",
                            value ? { status: "answered", value } : UNASKED
                          )
                        }
                      />
                    )}
                  </AskField>

                  <AskTextField
                    askId="place"
                    label="場所"
                    hint="「◯◯交差点の近く」くらいで大丈夫です。"
                    answer={answers.place}
                    onAnswerChange={(answer) => setAnswer("place", answer)}
                    placeholder="例：桜見台3丁目の交差点あたり"
                    render={({ controlId, describedBy, value, placeholder, onValueChange }) => (
                      <Input
                        id={controlId}
                        aria-describedby={describedBy}
                        value={value}
                        placeholder={placeholder}
                        onChange={(event) => onValueChange(event.target.value)}
                      />
                    )}
                  />

                  <AskSelectField
                    askId="weather"
                    label="天候"
                    answer={answers.weather}
                    onAnswerChange={(answer) => setAnswer("weather", answer)}
                    options={WEATHER_OPTIONS}
                  />

                  <AskSelectField
                    askId="road"
                    label="路面"
                    answer={answers.road}
                    onAnswerChange={(answer) => setAnswer("road", answer)}
                    options={ROAD_OPTIONS}
                  />

                  <div className="rounded-lg border border-border bg-card px-3 py-3">
                    <label htmlFor="call-memo" className="text-sm font-medium text-foreground">
                      通話メモ（そのまま書き取って構いません）
                    </label>
                    <Textarea
                      id="call-memo"
                      className="mt-2 w-full"
                      rows={3}
                      value={memo}
                      placeholder="お話しになった順に、そのまま書き留めてください。"
                      onChange={(event) => setMemo(event.target.value)}
                    />
                  </div>
                </VStack>
              </CardContent>
            </Card>

            {/* -------------------------------------------------------- 相手 */}
            <Card id="sec-other">
              <CardHeader>
                <CardTitle as="h2">相手</CardTitle>
                <p className="text-sm text-muted-foreground">
                  分かる範囲で構いません。その場で聞けなければ、あとから足せます。
                </p>
              </CardHeader>
              <CardContent>
                <VStack gap={3}>
                  <AskChoiceField
                    askId="otherParty"
                    label="相手がいるか"
                    answer={answers.otherParty}
                    onAnswerChange={(answer) => setAnswer("otherParty", answer)}
                    options={[
                      { value: "いる", label: "いる" },
                      { value: "いない", label: "いない", meansNone: true },
                    ]}
                  />

                  <RevealSection open={hasOtherParty} label="相手について聞くこと">
                    <VStack gap={3}>
                      <AskTextField
                        askId="otherName"
                        label="相手のお名前"
                        answer={answers.otherName}
                        onAnswerChange={(answer) => setAnswer("otherName", answer)}
                        placeholder="例：笹倉"
                        render={({ controlId, describedBy, value, placeholder, onValueChange }) => (
                          <Input
                            id={controlId}
                            aria-describedby={describedBy}
                            value={value}
                            placeholder={placeholder}
                            onChange={(event) => onValueChange(event.target.value)}
                          />
                        )}
                      />
                      <AskTextField
                        askId="otherPhone"
                        label="相手の連絡先"
                        hint="その場で聞けないことも多い項目です。"
                        answer={answers.otherPhone}
                        onAnswerChange={(answer) => setAnswer("otherPhone", answer)}
                        placeholder="例：090-0000-0000"
                        render={({ controlId, describedBy, value, placeholder, onValueChange }) => (
                          <Input
                            id={controlId}
                            type="tel"
                            inputMode="tel"
                            aria-describedby={describedBy}
                            value={value}
                            placeholder={placeholder}
                            onChange={(event) => onValueChange(event.target.value)}
                          />
                        )}
                      />
                      <AskTextField
                        askId="otherCar"
                        label="相手の車"
                        hint="色と大きさだけでも構いません。"
                        answer={answers.otherCar}
                        onAnswerChange={(answer) => setAnswer("otherCar", answer)}
                        placeholder="例：白い軽自動車、ナンバーは分からない"
                        allowNone
                        noneLabel="車ではない（自転車・歩行者など）"
                        render={({ controlId, describedBy, value, placeholder, onValueChange }) => (
                          <Input
                            id={controlId}
                            aria-describedby={describedBy}
                            value={value}
                            placeholder={placeholder}
                            onChange={(event) => onValueChange(event.target.value)}
                          />
                        )}
                      />
                    </VStack>
                  </RevealSection>
                </VStack>
              </CardContent>
            </Card>

            {/* ------------------------------------------------ けが・警察 */}
            <Card id="sec-safety">
              <CardHeader>
                <CardTitle as="h2">けが・警察</CardTitle>
                <p className="text-sm text-muted-foreground">
                  けがの詳しい内容は、この画面では聞きません。いるかどうかと、救急車を呼んだかどうかまでです。
                </p>
              </CardHeader>
              <CardContent>
                <VStack gap={3}>
                  <AskChoiceField
                    askId="injury"
                    label="けが人がいるか"
                    answer={answers.injury}
                    onAnswerChange={(answer) => setAnswer("injury", answer)}
                    options={[
                      { value: "いる", label: "いる" },
                      { value: "いない", label: "いない", meansNone: true },
                    ]}
                  />
                  <AskChoiceField
                    askId="ambulance"
                    label="救急車を呼んだか"
                    answer={answers.ambulance}
                    onAnswerChange={(answer) => setAnswer("ambulance", answer)}
                    options={[
                      { value: "呼んだ", label: "呼んだ" },
                      { value: "呼んでいない", label: "呼んでいない", meansNone: true },
                    ]}
                  />
                  <AskChoiceField
                    askId="police"
                    label="警察へ届け出たか"
                    hint="まだのときは、通話のあとで届け出ていただくご案内をします。"
                    answer={answers.police}
                    onAnswerChange={(answer) => setAnswer("police", answer)}
                    options={[
                      { value: "届け出た", label: "届け出た" },
                      { value: "していない", label: "していない", meansNone: true },
                    ]}
                  />
                </VStack>
              </CardContent>
            </Card>

            {/* ---------------------------------------------------- 車の状態 */}
            <Card id="sec-vehicle">
              <CardHeader>
                <CardTitle as="h2">車の状態</CardTitle>
                <p className="text-sm text-muted-foreground">
                  動くかどうかで、このあとの手配が変わります。
                </p>
              </CardHeader>
              <CardContent>
                <VStack gap={3}>
                  <AskChoiceField
                    askId="drivable"
                    label="車が動くか"
                    answer={answers.drivable}
                    onAnswerChange={(answer) => setAnswer("drivable", answer)}
                    options={[
                      { value: "動く", label: "動く" },
                      { value: "動かない", label: "動かない" },
                    ]}
                  />
                  <AskTextField
                    askId="carPlace"
                    label="車がいまある場所"
                    hint="路上か、脇に寄せられているかだけでも構いません。"
                    answer={answers.carPlace}
                    onAnswerChange={(answer) => setAnswer("carPlace", answer)}
                    placeholder="例：交差点の角の駐車場に入れています"
                    render={({ controlId, describedBy, value, placeholder, onValueChange }) => (
                      <Input
                        id={controlId}
                        aria-describedby={describedBy}
                        value={value}
                        placeholder={placeholder}
                        onChange={(event) => onValueChange(event.target.value)}
                      />
                    )}
                  />
                </VStack>
              </CardContent>
            </Card>

            {/* -------------------------------------------------- すぐの手配 */}
            <Card id="sec-dispatch">
              <CardHeader>
                <CardTitle as="h2">すぐの手配</CardTitle>
                <p className="text-sm text-muted-foreground">
                  頼んだかどうかと、返事が来たかどうかが、それぞれ残ります。
                </p>
              </CardHeader>
              <CardContent>
                <VStack gap={4}>
                  <DispatchBlock
                    askId="towNeed"
                    heading="レッカー"
                    glyph={IconTruckDelivery}
                    state={tow}
                    onNeedChange={(need) => setTow((current) => ({ ...current, need }))}
                    onRequest={() =>
                      requestDispatch(setTow, "受けられます。到着まで約40分の見込みです。")
                    }
                    requestLabel="レッカーの手配を依頼する"
                    coverageNote={
                      contract === null
                        ? "契約が特定できていないので、費用の扱いは後日の確認になります。手配自体は進められます。"
                        : towIncluded
                          ? contract.coverages.find((item) => item.key === "tow")?.note
                          : "この契約ではレッカーの費用は出ません。自費でのご案内になります。"
                    }
                  />

                  <Separator />

                  <DispatchBlock
                    askId="rentalNeed"
                    heading="代車"
                    glyph={IconCarGarage}
                    state={rental}
                    onNeedChange={(need) => setRental((current) => ({ ...current, need }))}
                    onRequest={() =>
                      requestDispatch(setRental, "明日の午前中にお渡しできます。")
                    }
                    requestLabel="代車の手配を依頼する"
                    coverageNote={
                      contract === null
                        ? "契約が特定できていないので、費用の扱いは後日の確認になります。手配自体は進められます。"
                        : rentalIncluded
                          ? contract.coverages.find((item) => item.key === "rental")?.note
                          : "この契約に代車は付いていません。自費でのご案内になります。"
                    }
                  />
                </VStack>
              </CardContent>
            </Card>

            {/* ------------------------------------------------ 受付を終える */}
            <Card id="sec-close">
              <CardHeader>
                <CardTitle as="h2">受付を終える</CardTitle>
                <p className="text-sm text-muted-foreground">
                  次に誰がいつ連絡するかを決めてから終えます。そのままお伝えできる言い方で出ます。
                </p>
              </CardHeader>
              <CardContent>
                <VStack gap={4}>
                  <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                    <Select
                      label="次に連絡する担当"
                      value={nextOwner}
                      onChange={(event) => setNextOwner(event.target.value)}
                      disabled={receiptNo !== null}
                    >
                      {NEXT_OWNERS.map((owner) => (
                        <option key={owner} value={owner}>
                          {owner}
                        </option>
                      ))}
                    </Select>
                    <Select
                      label="いつ連絡するか"
                      value={nextTiming}
                      onChange={(event) => setNextTiming(event.target.value)}
                      disabled={receiptNo !== null}
                    >
                      {NEXT_TIMINGS.map((timing) => (
                        <option key={timing} value={timing}>
                          {timing}
                        </option>
                      ))}
                    </Select>
                  </div>

                  {receiptNo === null ? (
                    <VStack gap={3}>
                      <p className="text-sm text-muted-foreground">
                        まだ聞いていない項目が {unaskedCount}件 あります。そのままでも受け付けられます。
                        {withoutContract || contract === null
                          ? " 契約が分からないままでも構いません。"
                          : null}
                      </p>
                      <Cluster gap={2}>
                        <Button
                          type="button"
                          variant="primary"
                          onClick={() => setReceiptNo(NEXT_RECEIPT_NO)}
                        >
                          受付を確定する
                        </Button>
                      </Cluster>
                    </VStack>
                  ) : (
                    <VStack gap={3}>
                      <div className="rounded-lg border border-border bg-muted/40 px-4 py-4">
                        <h3 className="text-sm font-semibold text-foreground">
                          このままお伝えできます
                        </h3>
                        <p className="mt-2 text-2xl font-bold tracking-tight text-foreground">
                          {receiptNo}
                        </p>
                        <p className="mt-2 text-base leading-relaxed text-foreground">{spokenText}</p>
                        <p className="mt-2 text-sm text-muted-foreground">
                          番号を控えられなくても、お電話いただければこちらでお調べできます。
                        </p>
                        <div className="mt-3">
                          <CopyButton
                            value={spokenText}
                            variant="label"
                            buttonVariant="outline"
                            copyLabel="お伝えする言い方を写す"
                            copiedLabel="写しました"
                          />
                        </div>
                      </div>
                      <Cluster gap={2}>
                        <Button type="button" variant="outline" onClick={resetAll}>
                          新しい受付を始める
                        </Button>
                      </Cluster>
                    </VStack>
                  )}
                </VStack>
              </CardContent>
            </Card>
          </main>

          <aside aria-label="受付の控え" className="flex min-w-0 flex-col gap-4">
            <HearingProgress items={progressItems} />
            <TodayList />
          </aside>
        </div>
      </div>
    </div>
  )
}

/* ------------------------------------------------------------ 手配ひとつ分 */

function DispatchBlock({
  askId,
  heading,
  glyph,
  state,
  onNeedChange,
  onRequest,
  requestLabel,
  coverageNote,
}: {
  askId: string
  heading: string
  glyph: React.ComponentProps<typeof Icon>["icon"]
  state: DispatchState
  onNeedChange: (need: Answer) => void
  onRequest: () => void
  requestLabel: string
  coverageNote?: string
}) {
  const needed = state.need.status === "answered" && state.need.value === "要る"

  return (
    <section aria-labelledby={`dispatch-${askId}`}>
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <h3 id={`dispatch-${askId}`} className="flex items-center gap-2 text-sm font-semibold text-foreground">
          <Icon icon={glyph} size="sm" decorative />
          {heading}
        </h3>
        {state.requestedAt === null ? (
          <Badge variant="outline" icon={<Icon icon={IconCircleDashed} size="xs" decorative />}>
            まだ頼んでいない
          </Badge>
        ) : state.answeredAt === null ? (
          <Badge variant="info" icon={<Icon icon={IconClock} size="xs" decorative />}>
            頼みました・返事待ち
          </Badge>
        ) : (
          <Badge variant="success" icon={<Icon icon={IconCircleCheck} size="xs" decorative />}>
            返事が来ました
          </Badge>
        )}
      </div>

      <VStack gap={3}>
        <AskChoiceField
          askId={askId}
          label={`${heading}が要るか`}
          answer={state.need}
          onAnswerChange={onNeedChange}
          options={[
            { value: "要る", label: "要る" },
            { value: "要らない", label: "要らない", meansNone: true },
          ]}
        />

        {coverageNote ? (
          <p className="text-xs text-muted-foreground">{coverageNote}</p>
        ) : null}

        <RevealSection open={needed} label={`${heading}の手配`}>
          <VStack gap={2}>
            {state.requestedAt === null ? (
              <Cluster gap={2}>
                <Button type="button" variant="primary" onClick={onRequest}>
                  {requestLabel}
                </Button>
              </Cluster>
            ) : (
              <div className="rounded-lg border border-border bg-card px-3 py-3">
                <p className="text-sm text-foreground">{state.requestedAt} に手配を依頼しました。</p>
                {state.answeredAt ? (
                  <p className="mt-1 text-sm text-foreground">
                    {state.answeredAt} 返事：{state.reply}
                  </p>
                ) : (
                  <p className="mt-1 flex items-center gap-1.5 text-sm text-muted-foreground">
                    <Icon icon={IconClock} size="sm" decorative />
                    まだ返事は来ていません。
                  </p>
                )}
              </div>
            )}
          </VStack>
        </RevealSection>
      </VStack>
    </section>
  )
}

"use client"

/**
 * AskField — 聞き取り1項目の入れもの（この画面で自前に組んだ部品）
 *
 * @gunjo/ui には「まだ聞いていない」と「無いと確認した」を見分けて見せる部品が無い。
 * Input / Select / Checkbox はどれも「値が入っているか」しか持たないので、
 * 空欄のままだと『聞き忘れ』と『無いと答えられた』が同じ見た目になってしまう。
 * そこでここだけ自前で組み、状態は次の4つを持たせている。
 *
 *   まだ聞いていない … 破線の枠＋薄い地色（EmptyState と同じ言い方）＋バッジ
 *   記録した         … 実線の枠＋バッジ
 *   無いと確認       … 実線の枠＋バッジ（中身は「いない」など）
 *   ご本人も分からない … 実線の枠＋バッジ
 *
 * 色だけに意味を持たせない（バッジは必ずアイコン＋文字）。
 */

import * as React from "react"
import {
  Badge,
  Button,
  Icon,
  SegmentedControl,
  Select,
  cn,
  type BadgeVariantKey,
  type IconGlyph,
} from "@gunjo/ui"
import {
  IconArrowBackUp,
  IconCircleCheck,
  IconCircleDashed,
  IconCircleMinus,
  IconHelpCircle,
} from "@tabler/icons-react"

import type { Answer, AnswerStatus } from "./types"

const STATUS_META: Record<
  AnswerStatus,
  { label: string; variant: BadgeVariantKey; glyph: IconGlyph }
> = {
  unasked: { label: "まだ聞いていない", variant: "outline", glyph: IconCircleDashed },
  answered: { label: "記録した", variant: "success", glyph: IconCircleCheck },
  none: { label: "無いと確認", variant: "secondary", glyph: IconCircleMinus },
  unknown: { label: "分からない", variant: "info", glyph: IconHelpCircle },
}

export function answerStatusLabel(status: AnswerStatus): string {
  return STATUS_META[status].label
}

export function AnswerStatusBadge({
  status,
  id,
  size = "default",
}: {
  status: AnswerStatus
  id?: string
  size?: "sm" | "default"
}) {
  const meta = STATUS_META[status]
  return (
    <Badge id={id} variant={meta.variant} size={size} icon={<Icon icon={meta.glyph} size="xs" decorative />}>
      {meta.label}
    </Badge>
  )
}

const SURFACE: Record<AnswerStatus, string> = {
  // 破線＋薄い地色は @gunjo/ui の EmptyState と同じ言い方。「まだ何も無い」の合図。
  unasked: "border-dashed bg-muted/40",
  answered: "bg-card",
  none: "bg-card",
  unknown: "bg-card",
}

export interface AskFieldRenderContext {
  controlId: string
  labelId: string
  describedBy: string
}

export interface AskFieldProps {
  askId: string
  label: React.ReactNode
  hint?: React.ReactNode
  answer: Answer
  onAnswerChange: (answer: Answer) => void
  /** ラベルを <label for> にするか、グループの名前（span）にするか。 */
  labelAs?: "label" | "group"
  /** 答えが「無い」ときの1押しボタンを出す。 */
  allowNone?: boolean
  noneLabel?: string
  /** 答えが「分からない」ときの1押しボタンを出す。 */
  allowUnknown?: boolean
  /** 無い／分からない のときも入力そのものを出したままにする（選択式で使う）。 */
  keepControl?: boolean
  children: (context: AskFieldRenderContext) => React.ReactNode
}

export function AskField({
  askId,
  label,
  hint,
  answer,
  onAnswerChange,
  labelAs = "label",
  allowNone = false,
  noneLabel = "無いと確認",
  allowUnknown = true,
  keepControl = false,
  children,
}: AskFieldProps) {
  const controlId = `ask-${askId}-control`
  const labelId = `ask-${askId}-label`
  const hintId = `ask-${askId}-hint`
  const statusId = `ask-${askId}-status`
  const describedBy = [hint ? hintId : null, statusId].filter(Boolean).join(" ")

  const settled = answer.status === "none" || answer.status === "unknown"
  const showControl = keepControl || !settled

  const settledText =
    answer.status === "none"
      ? answer.value
        ? `${answer.value}（無いと確認しました）`
        : "無いと確認しました"
      : "ご本人も分からない、と確認しました"

  return (
    <div
      id={`ask-${askId}`}
      data-ask-status={answer.status}
      className={cn("rounded-lg border border-border px-3 py-3", SURFACE[answer.status])}
    >
      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
        {labelAs === "label" && showControl ? (
          <label id={labelId} htmlFor={controlId} className="text-sm font-medium text-foreground">
            {label}
          </label>
        ) : (
          <span id={labelId} className="text-sm font-medium text-foreground">
            {label}
          </span>
        )}
        <AnswerStatusBadge status={answer.status} id={statusId} size="sm" />
      </div>

      {hint ? (
        <p id={hintId} className="mt-1 text-xs text-muted-foreground">
          {hint}
        </p>
      ) : null}

      <div className="mt-2">
        {showControl ? (
          children({ controlId, labelId, describedBy })
        ) : (
          <p className="text-sm text-foreground">{settledText}</p>
        )}
      </div>

      <div className="mt-2 flex flex-wrap items-center gap-1.5">
        {allowNone && answer.status !== "none" ? (
          <Button
            type="button"
            size="xs"
            variant="outline"
            onClick={() => onAnswerChange({ status: "none", value: "" })}
          >
            {noneLabel}
          </Button>
        ) : null}
        {allowUnknown && answer.status !== "unknown" ? (
          <Button
            type="button"
            size="xs"
            variant="outline"
            onClick={() => onAnswerChange({ status: "unknown", value: "" })}
          >
            分からない
          </Button>
        ) : null}
        {answer.status !== "unasked" ? (
          <Button
            type="button"
            size="xs"
            variant="ghost"
            onClick={() => onAnswerChange({ status: "unasked", value: "" })}
          >
            <Icon icon={IconArrowBackUp} size="xs" decorative />
            まだ聞いていない に戻す
          </Button>
        ) : null}
      </div>
    </div>
  )
}

/* ------------------------------------------------------------ 文字で聞く */

export function AskTextField({
  askId,
  label,
  hint,
  answer,
  onAnswerChange,
  placeholder,
  allowNone = false,
  noneLabel,
  allowUnknown = true,
  render,
}: {
  askId: string
  label: React.ReactNode
  hint?: React.ReactNode
  answer: Answer
  onAnswerChange: (answer: Answer) => void
  placeholder?: string
  allowNone?: boolean
  noneLabel?: string
  allowUnknown?: boolean
  render: (
    context: AskFieldRenderContext & {
      value: string
      placeholder?: string
      onValueChange: (value: string) => void
    }
  ) => React.ReactNode
}) {
  return (
    <AskField
      askId={askId}
      label={label}
      hint={hint}
      answer={answer}
      onAnswerChange={onAnswerChange}
      allowNone={allowNone}
      noneLabel={noneLabel}
      allowUnknown={allowUnknown}
    >
      {(context) =>
        render({
          ...context,
          value: answer.status === "answered" ? answer.value : "",
          placeholder,
          // 打ち始めたら「記録した」に、消したら「まだ聞いていない」に戻る。
          onValueChange: (value: string) =>
            onAnswerChange(
              value.trim().length === 0
                ? { status: "unasked", value: "" }
                : { status: "answered", value }
            ),
        })
      }
    </AskField>
  )
}

/* ------------------------------------------------------ 選んでもらって聞く */

export interface AskChoiceOption {
  value: string
  label: string
  /** 「いない」「呼んでいない」など、無いという答え。 */
  meansNone?: boolean
}

/** 2〜3択。「分からない」も選択肢の中に置いて、1押しで済むようにする。 */
export function AskChoiceField({
  askId,
  label,
  hint,
  answer,
  onAnswerChange,
  options,
  unknownLabel = "分からない",
}: {
  askId: string
  label: React.ReactNode
  hint?: React.ReactNode
  answer: Answer
  onAnswerChange: (answer: Answer) => void
  options: AskChoiceOption[]
  unknownLabel?: string
}) {
  const UNKNOWN_VALUE = "__unknown__"
  const segments = [
    ...options.map((option) => ({ value: option.value, label: option.label })),
    { value: UNKNOWN_VALUE, label: unknownLabel },
  ]
  const current =
    answer.status === "unknown" ? UNKNOWN_VALUE : answer.status === "unasked" ? "" : answer.value

  return (
    <AskField
      askId={askId}
      label={label}
      hint={hint}
      answer={answer}
      onAnswerChange={onAnswerChange}
      labelAs="group"
      allowNone={false}
      allowUnknown={false}
      keepControl
    >
      {({ controlId, labelId, describedBy }) => (
        <SegmentedControl
          id={controlId}
          aria-labelledby={labelId}
          aria-describedby={describedBy}
          options={segments}
          value={current}
          onValueChange={(value) => {
            if (value === UNKNOWN_VALUE) {
              onAnswerChange({ status: "unknown", value: "" })
              return
            }
            const picked = options.find((option) => option.value === value)
            onAnswerChange({
              status: picked?.meansNone ? "none" : "answered",
              value,
            })
          }}
        />
      )}
    </AskField>
  )
}

/** 4択以上。横に並べると読めなくなるので、選ぶ形にする。 */
export function AskSelectField({
  askId,
  label,
  hint,
  answer,
  onAnswerChange,
  options,
}: {
  askId: string
  label: React.ReactNode
  hint?: React.ReactNode
  answer: Answer
  onAnswerChange: (answer: Answer) => void
  options: string[]
}) {
  const UNKNOWN_VALUE = "__unknown__"
  const current =
    answer.status === "unknown" ? UNKNOWN_VALUE : answer.status === "answered" ? answer.value : ""

  return (
    <AskField
      askId={askId}
      label={label}
      hint={hint}
      answer={answer}
      onAnswerChange={onAnswerChange}
      allowNone={false}
      allowUnknown={false}
      keepControl
    >
      {({ controlId, describedBy }) => (
        <Select
          id={controlId}
          aria-describedby={describedBy}
          value={current}
          onChange={(event) => {
            const value = event.target.value
            if (value === "") {
              onAnswerChange({ status: "unasked", value: "" })
              return
            }
            if (value === UNKNOWN_VALUE) {
              onAnswerChange({ status: "unknown", value: "" })
              return
            }
            onAnswerChange({ status: "answered", value })
          }}
        >
          <option value="">まだ聞いていない</option>
          {options.map((option) => (
            <option key={option} value={option}>
              {option}
            </option>
          ))}
          <option value={UNKNOWN_VALUE}>分からない</option>
        </Select>
      )}
    </AskField>
  )
}

