import * as React from "react"
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Button,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CheckList,
  Cluster,
  Form,
  HStack,
  Icon,
  ListCard,
  MetadataList,
  SearchInput,
  SegmentedControl,
  Skeleton,
  VStack,
  type BadgeVariantKey,
  type IconGlyph,
} from "@gunjo/ui"
import {
  IconAlertTriangle,
  IconCircleCheck,
  IconCircleMinus,
  IconSearch,
} from "@tabler/icons-react"

import { SEARCH_KEYS, searchContracts, type Contract, type SearchKey } from "./data"

const CONTRACT_STATUS: Record<
  Contract["status"],
  { label: string; variant: BadgeVariantKey; glyph: IconGlyph }
> = {
  active: { label: "いま有効", variant: "success", glyph: IconCircleCheck },
  expired: { label: "満了ずみ", variant: "secondary", glyph: IconCircleMinus },
  suspended: { label: "補償が止まっています", variant: "warning", glyph: IconAlertTriangle },
}

export function ContractStatusBadge({ status }: { status: Contract["status"] }) {
  const meta = CONTRACT_STATUS[status]
  return (
    <Badge variant={meta.variant} icon={<Icon icon={meta.glyph} size="xs" decorative />}>
      {meta.label}
    </Badge>
  )
}

export interface ContractFinderProps {
  selected: Contract | null
  onSelect: (contract: Contract | null) => void
  withoutContract: boolean
  onWithoutContractChange: (value: boolean) => void
}

export function ContractFinder({
  selected,
  onSelect,
  withoutContract,
  onWithoutContractChange,
}: ContractFinderProps) {
  const [searchKey, setSearchKey] = React.useState<SearchKey>("policy")
  const [query, setQuery] = React.useState("")
  const [searching, setSearching] = React.useState(false)
  const [results, setResults] = React.useState<Contract[] | null>(null)

  const keyMeta = SEARCH_KEYS.find((item) => item.value === searchKey) ?? SEARCH_KEYS[0]

  const runSearch = () => {
    if (query.trim().length === 0) return
    setSearching(true)
    setResults(null)
    window.setTimeout(() => {
      setResults(searchContracts(searchKey, query))
      setSearching(false)
    }, 700)
  }

  return (
    <Card id="sec-contract" className="scroll-mt-24">
      <CardHeader>
        <HStack justify="between" align="center" wrap gap={2}>
          <CardTitle as="h2">契約を探す</CardTitle>
          {selected ? <ContractStatusBadge status={selected.status} /> : null}
        </HStack>
        <p className="text-sm text-muted-foreground">
          証券番号・契約者の氏名・車のナンバーのどれかで探せます。見つからなくても受け付けは進められます。
        </p>
      </CardHeader>

      <CardContent>
        {selected ? (
          <VStack gap={4}>
            <MetadataList
              wrap
              items={[
                { label: "証券番号", value: selected.policyNo },
                { label: "契約者", value: `${selected.holder}（${selected.holderKana}）` },
                { label: "電話", value: selected.phone },
                { label: "車", value: `${selected.car} ／ ${selected.plate}` },
                { label: "保険期間", value: selected.term },
                { label: "いまの状態", value: selected.statusNote },
              ]}
            />

            <section aria-labelledby="coverage-heading">
              <h3 id="coverage-heading" className="mb-2 text-sm font-semibold text-foreground">
                この契約で使えるもの
              </h3>
              <CheckList
                items={selected.coverages.map((coverage) => ({
                  id: coverage.key,
                  label: coverage.label,
                  description: coverage.note,
                  trailing: (
                    <Badge
                      variant={coverage.included ? "success" : "secondary"}
                      icon={
                        <Icon
                          icon={coverage.included ? IconCircleCheck : IconCircleMinus}
                          size="xs"
                          decorative
                        />
                      }
                    >
                      {coverage.included ? "使える" : "使えない"}
                    </Badge>
                  ),
                }))}
              />
            </section>

            {selected.status !== "active" ? (
              <Alert variant="warning" icon={<Icon icon={IconAlertTriangle} size="sm" decorative />}>
                <AlertTitle>この契約はいま使えません</AlertTitle>
                <AlertDescription>
                  {selected.statusNote} 受け付けはこのまま進められます。手配が要るときは契約担当へつないでください。
                </AlertDescription>
              </Alert>
            ) : null}

            <Cluster gap={2}>
              <Button type="button" variant="outline" onClick={() => onSelect(null)}>
                別の契約を探す
              </Button>
            </Cluster>
          </VStack>
        ) : withoutContract ? (
          <VStack gap={3}>
            <Alert variant="info">
              <AlertTitle>契約が分からないまま受け付けています</AlertTitle>
              <AlertDescription>
                契約者以外の方からのご連絡でも、このまま最後まで受け付けられます。契約はあとから結び付けられます。
              </AlertDescription>
            </Alert>
            <Cluster gap={2}>
              <Button type="button" variant="outline" onClick={() => onWithoutContractChange(false)}>
                やはり契約を探す
              </Button>
            </Cluster>
          </VStack>
        ) : (
          <VStack gap={4}>
            <Form
              className="gap-2"
              onSubmit={(event) => {
                event.preventDefault()
                runSearch()
              }}
            >
              <VStack gap={2}>
                <span id="search-key-label" className="text-sm font-medium text-foreground">
                  何で探しますか
                </span>
                <SegmentedControl
                  aria-labelledby="search-key-label"
                  options={SEARCH_KEYS.map((item) => ({ value: item.value, label: item.short }))}
                  value={searchKey}
                  onValueChange={(value) => {
                    setSearchKey(value as SearchKey)
                    setResults(null)
                  }}
                />
                <label htmlFor="contract-query" className="text-sm font-medium text-foreground">
                  {keyMeta.label}
                </label>
                <div className="flex flex-wrap items-center gap-2">
                  <SearchInput
                    id="contract-query"
                    className="min-w-0 flex-1"
                    aria-describedby="contract-query-hint"
                    placeholder={keyMeta.placeholder}
                    value={query}
                    onValueChange={setQuery}
                  />
                  <Button type="submit" variant="primary" loading={searching}>
                    <Icon icon={IconSearch} size="sm" decorative />
                    探す
                  </Button>
                </div>
                <p id="contract-query-hint" className="text-xs text-muted-foreground">
                  {keyMeta.hint}
                </p>
              </VStack>
            </Form>

            {searching ? (
              <div role="status" aria-live="polite" className="rounded-lg border border-border p-3">
                <span className="sr-only">契約を探しています</span>
                <VStack gap={2} aria-hidden="true">
                  <Skeleton className="h-4 w-2/3" />
                  <Skeleton className="h-4 w-1/2" />
                </VStack>
              </div>
            ) : null}

            {!searching && results !== null && results.length > 0 ? (
              <VStack gap={2} aria-label="見つかった契約">
                <p className="text-sm text-muted-foreground">{results.length}件 見つかりました。</p>
                {results.map((contract) => (
                  <ListCard
                    key={contract.id}
                    title={`${contract.holder}（${contract.policyNo}）`}
                    description={`${contract.car} ／ ${contract.plate}`}
                    status={<ContractStatusBadge status={contract.status} />}
                    onSelect={() => onSelect(contract)}
                  />
                ))}
              </VStack>
            ) : null}

            {!searching && results !== null && results.length === 0 ? (
              <Alert variant="default">
                <AlertTitle>見つかりませんでした</AlertTitle>
                <AlertDescription>
                  別の探し方に切り替えるか、契約が分からないまま受け付けを進めてください。
                </AlertDescription>
              </Alert>
            ) : null}

            <Cluster gap={2}>
              <Button type="button" variant="outline" onClick={() => onWithoutContractChange(true)}>
                契約が分からないまま進める
              </Button>
            </Cluster>
          </VStack>
        )}
      </CardContent>
    </Card>
  )
}

"use client"

import * as React from "react"
import {
  Badge,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  Cluster,
  Icon,
  NavRow,
  SettingGroup,
  VStack,
} from "@gunjo/ui"
import {
  IconCircleCheck,
  IconCircleDashed,
  IconCircleMinus,
  IconHelpCircle,
} from "@tabler/icons-react"

import { AnswerStatusBadge } from "./AskField"
import { SECTION_LABEL } from "./data"
import type { AnswerStatus, AskMeta } from "./types"

export interface ProgressItem extends AskMeta {
  status: AnswerStatus
}

/**
 * 聞き取りの状況 — 「まだ聞いていない」項目がひと目で分かる控え。
 * 行を押すと、その項目まで画面が動いて入力に焦点が移る（通話中に探し回らないため）。
 */
export function HearingProgress({ items }: { items: ProgressItem[] }) {
  const count = (status: AnswerStatus) => items.filter((item) => item.status === status).length

  const jumpTo = (askId: string) => {
    const target = document.getElementById(`ask-${askId}`)
    if (!target) return
    target.scrollIntoView({ behavior: "smooth", block: "center" })
    const focusable = target.querySelector<HTMLElement>("input, textarea, select, button")
    focusable?.focus({ preventScroll: true })
  }

  const sections = Array.from(new Set(items.map((item) => item.section)))

  return (
    <Card id="sec-progress">
      <CardHeader>
        <CardTitle as="h2">聞き取りの状況</CardTitle>
        <p className="text-sm text-muted-foreground">
          聞けていない項目は、空欄ではなく「まだ聞いていない」として残ります。順番どおりでなくて構いません。
        </p>
      </CardHeader>
      <CardContent>
        <VStack gap={4}>
          <Cluster gap={2}>
            <Badge variant="success" icon={<Icon icon={IconCircleCheck} size="xs" decorative />}>
              記録した {count("answered")}
            </Badge>
            <Badge variant="secondary" icon={<Icon icon={IconCircleMinus} size="xs" decorative />}>
              無いと確認 {count("none")}
            </Badge>
            <Badge variant="info" icon={<Icon icon={IconHelpCircle} size="xs" decorative />}>
              分からない {count("unknown")}
            </Badge>
            <Badge variant="outline" icon={<Icon icon={IconCircleDashed} size="xs" decorative />}>
              まだ聞いていない {count("unasked")}
            </Badge>
          </Cluster>

          {sections.map((section) => (
            <div key={section}>
              <h3 className="mb-1.5 px-1 text-xs font-semibold text-muted-foreground">
                {SECTION_LABEL[section] ?? section}
              </h3>
              <SettingGroup>
                {items
                  .filter((item) => item.section === section)
                  .map((item) => (
                    <NavRow
                      key={item.id}
                      label={item.label}
                      value={<AnswerStatusBadge status={item.status} size="sm" />}
                      onSelect={() => jumpTo(item.id)}
                    />
                  ))}
              </SettingGroup>
            </div>
          ))}
        </VStack>
      </CardContent>
    </Card>
  )
}

"use client"

import * as React from "react"
import {
  Badge,
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
  EmptyState,
  Icon,
  ListCard,
  SegmentedControl,
  Select,
