  VStack,
} from "@gunjo/ui"
import { IconCircleCheck, IconClipboardText, IconProgress } from "@tabler/icons-react"

import { TODAY_INTAKES, type IntakeRow } from "./data"

type ListFilter = "all" | "open" | "closed"
/** 見本の画面なので、読み込み中と0件も切り替えて確かめられるようにしてある。 */
type ListPhase = "ready" | "loading" | "empty"

function StateBadge({ state }: { state: IntakeRow["state"] }) {
  return state === "open" ? (
    <Badge variant="info" icon={<Icon icon={IconProgress} size="xs" decorative />}>
      対応中
    </Badge>
  ) : (
    <Badge variant="secondary" icon={<Icon icon={IconCircleCheck} size="xs" decorative />}>
      受付を終えた
    </Badge>
  )
}

export function TodayList() {
  const [filter, setFilter] = React.useState<ListFilter>("all")
  const [phase, setPhase] = React.useState<ListPhase>("ready")

  const rows = phase === "empty" ? [] : TODAY_INTAKES
  const shown = rows.filter((row) => (filter === "all" ? true : row.state === filter))
  const openCount = rows.filter((row) => row.state === "open").length
  const closedCount = rows.filter((row) => row.state === "closed").length

  return (
    <Card id="sec-today">
      <CardHeader>
        <CardTitle as="h2">本日の受付</CardTitle>
        <p className="text-sm text-muted-foreground">{rows.length}件（対応中 {openCount}件）</p>
      </CardHeader>

      <CardContent>
        <VStack gap={3}>
          <SegmentedControl
            aria-label="本日の受付のしぼり込み"
            size="sm"
            options={[
              { value: "all", label: `すべて ${rows.length}` },
              { value: "open", label: `対応中 ${openCount}` },
              { value: "closed", label: `受付済 ${closedCount}` },
            ]}
            value={filter}
            onValueChange={(value) => setFilter(value as ListFilter)}
          />

          {phase === "loading" ? (
            <div role="status" aria-live="polite">
              <span className="sr-only">本日の受付を読み込んでいます</span>
              <VStack gap={2} aria-hidden="true">
                {[0, 1, 2, 3].map((index) => (
                  <div key={index} className="rounded-lg border border-border p-3">
                    <Skeleton className="h-4 w-1/2" />
                    <Skeleton className="mt-2 h-3 w-3/4" />
                  </div>
                ))}
              </VStack>
            </div>
          ) : shown.length === 0 ? (
            <EmptyState
              headingLevel={3}
              icon={<Icon icon={IconClipboardText} size="lg" decorative />}
              title={phase === "empty" ? "本日の受付はまだありません" : "この絞り込みに当てはまる受付はありません"}
              description={
                phase === "empty"
                  ? "受け付けが済むと、ここに並びます。"
                  : "しぼり込みを「すべて」に戻すと、本日ぶんが出ます。"
              }
            />
          ) : (
            <VStack gap={2}>
              {shown.map((row) => (
                <ListCard
                  key={row.no}
                  title={row.no}
                  description={`${row.caller} ／ ${row.place}`}
                  status={<StateBadge state={row.state} />}
                  meta={`${row.receivedAt} 受付`}
                  tags={<span className="text-xs text-muted-foreground">{row.note}</span>}
                />
              ))}
            </VStack>
          )}
        </VStack>
      </CardContent>

      <CardFooter>
        <Select
          className="h-8 text-xs"
          label={<span className="text-xs text-muted-foreground">表示の確かめ（見本用）</span>}
          value={phase}
          onChange={(event) => setPhase(event.target.value as ListPhase)}
        >
          <option value="ready">本日ぶんを表示</option>
          <option value="loading">読み込み中</option>
          <option value="empty">0件のとき</option>
        </Select>
      </CardFooter>
    </Card>
  )
}

/**
 * 事故受付センター 受付画面 — 型定義
 *
 * この画面のいちばん大事な決まりごと:
 *   聞き取り項目は「空欄」ではなく「まだ聞いていない」という状態を持つ。
 *   後の調査で効くので、次の4つを取り違えないようにする。
 *     unasked  … まだ聞いていない（通話がそこまで行っていない）
 *     answered … 聞き取って記録した
 *     none     … 「無い」と答えられた（無いことを確認した）
 *     unknown  … ご本人も分からない、と答えられた
 */

export type AnswerStatus = "unasked" | "answered" | "none" | "unknown"

export interface Answer {
  status: AnswerStatus
  /** answered / none / unknown のときの中身。unasked のときは空。 */
  value: string
}

export const UNASKED: Answer = { status: "unasked", value: "" }

export type AskId =
  | "date"
  | "time"
  | "place"
  | "weather"
  | "road"
  | "otherParty"
  | "otherName"
  | "otherPhone"
  | "otherCar"
  | "injury"
  | "ambulance"
  | "police"
  | "drivable"
  | "carPlace"

export type SectionId = "situation" | "other" | "safety" | "vehicle"

export interface AskMeta {
  id: AskId
  /** 聞き取り一覧に出す短い名前。フォームの見出しと同じ言い方にする。 */
  label: string
  section: SectionId
  /** 「相手がいる」と答えられたときだけ聞く項目。 */
  onlyWhenOtherParty?: boolean
}

export type Answers = Record<AskId, Answer>

/** 手配（レッカー・代車）の状態。要否は聞き取り項目と同じ4状態を使う。 */
export interface DispatchState {
  /** 要る／要らない／分からない／まだ聞いていない。 */
  need: Answer
  /** 手配を頼んだ時刻。頼んでいなければ null。 */
  requestedAt: string | null
  /** 手配先から返事が来た時刻。まだなら null。 */
  answeredAt: string | null
  /** 返事の中身（到着の見込みなど）。 */
  reply: string | null
}

export const NO_DISPATCH: DispatchState = {
  need: UNASKED,
  requestedAt: null,
  answeredAt: null,
  reply: null,
}
